            [rect["x0"].as_f64(), rect["y0"].as_f64(), rect["x1"].as_f64(), rect["y1"].as_f64()].map(|value| (value.unwrap() * 1e9).round() / 1e9)
        };
        for (code, expected) in [
            ("AB", [0.1, 0.2, 0.6, 0.9]),
            ("BA", [0.4, 0.2, 0.9, 0.9]),
