        assert_eq!(
            [
                partial["crop"]["geometry"]["rect"]["x0"].as_f64(),
                partial["crop"]["geometry"]["rect"]["y0"].as_f64(),
                partial["crop"]["geometry"]["rect"]["x1"].as_f64(),
                partial["crop"]["geometry"]["rect"]["y1"].as_f64(),
            ]
            .map(|value| value.unwrap()),
